-- Settlement integration contract (SET-01, NFR-12). Either side of a settlement comparison is an
-- ordinary file with these columns; a tenant with a different layout drafts its own mapping.
--   settlement_key   stable id both sides share (settlement id, or the RRN/UTR of the payment)
--   settlement_ref   the record's own id on its side (optional)
--   batch_id         settlement batch (optional)
--   settlement_date  date the money is (expected to be / was) settled, yyyy-MM-dd
--   amount           decimal rupees; txn_time  yyyy-MM-dd'T'HH:mm:ssXXX; account, status optional
INSERT INTO mapping_definition (tenant_id, source_id, version, rail, active, field_mappings, created_by)
VALUES ('*', 'settlement_expected', 1, 'UPI', TRUE, '[{"canonicalField": "settlementKey", "sourceField": "settlement_key", "transformation": "REFERENCE"}, {"canonicalField": "settlementRef", "sourceField": "settlement_ref", "transformation": "DIRECT_COPY"}, {"canonicalField": "batchReference", "sourceField": "batch_id", "transformation": "DIRECT_COPY"}, {"canonicalField": "settlementDate", "sourceField": "settlement_date", "transformation": "DATE", "parameter": "yyyy-MM-dd"}, {"canonicalField": "amountMinor", "sourceField": "amount", "transformation": "AMOUNT_TO_MINOR"}, {"canonicalField": "transactionTimeUtc", "sourceField": "txn_time", "transformation": "TIMESTAMP", "parameter": "yyyy-MM-dd''T''HH:mm:ssXXX"}, {"canonicalField": "accountReference", "sourceField": "account", "transformation": "DIRECT_COPY"}, {"canonicalField": "direction", "sourceField": "_direction", "transformation": "DIRECT_COPY", "defaultValue": "CREDIT"}, {"canonicalField": "transactionStatus", "sourceField": "status", "transformation": "VALUE_MAP", "parameter": "SETTLED=SUCCESS,SUCCESS=SUCCESS,PENDING=PENDING,FAILED=FAILED,REVERSED=REVERSED", "defaultValue": "SUCCESS"}, {"canonicalField": "recordKind", "sourceField": "_kind", "transformation": "DIRECT_COPY", "defaultValue": "SETTLEMENT_EXPECTED"}]', 'system');
INSERT INTO mapping_definition (tenant_id, source_id, version, rail, active, field_mappings, created_by)
VALUES ('*', 'settlement_actual', 1, 'UPI', TRUE, '[{"canonicalField": "settlementKey", "sourceField": "settlement_key", "transformation": "REFERENCE"}, {"canonicalField": "settlementRef", "sourceField": "settlement_ref", "transformation": "DIRECT_COPY"}, {"canonicalField": "batchReference", "sourceField": "batch_id", "transformation": "DIRECT_COPY"}, {"canonicalField": "settlementDate", "sourceField": "settlement_date", "transformation": "DATE", "parameter": "yyyy-MM-dd"}, {"canonicalField": "amountMinor", "sourceField": "amount", "transformation": "AMOUNT_TO_MINOR"}, {"canonicalField": "transactionTimeUtc", "sourceField": "txn_time", "transformation": "TIMESTAMP", "parameter": "yyyy-MM-dd''T''HH:mm:ssXXX"}, {"canonicalField": "accountReference", "sourceField": "account", "transformation": "DIRECT_COPY"}, {"canonicalField": "direction", "sourceField": "_direction", "transformation": "DIRECT_COPY", "defaultValue": "CREDIT"}, {"canonicalField": "transactionStatus", "sourceField": "status", "transformation": "VALUE_MAP", "parameter": "SETTLED=SUCCESS,SUCCESS=SUCCESS,PENDING=PENDING,FAILED=FAILED,REVERSED=REVERSED", "defaultValue": "SUCCESS"}, {"canonicalField": "recordKind", "sourceField": "_kind", "transformation": "DIRECT_COPY", "defaultValue": "SETTLEMENT_ACTUAL"}]', 'system');
